head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst80700";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst80700.onpageload' });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    await scwin.fnSearchInit();
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.init();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst80700.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name searchForm_onsubmit
 * @description searchForm onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.searchForm_onsubmit = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst80700.searchForm_onsubmit' }); }
};

/**
 * @method
 * @name btn_fnSearchInit_onclick
 * @description btn_fnSearchInit 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnSearchInit_onclick = async function(e){
    try {
        await scwin.fnSearchInit(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst80700.btn_fnSearchInit_onclick' }); }
};

/**
 * @method
 * @name btn_fnAllSearch_onclick
 * @description btn_fnAllSearch 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnAllSearch_onclick = async function(e){
    try {
        await scwin.fnAllSearch(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst80700.btn_fnAllSearch_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_FileDown
 * @description File Down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_FileDown = async function () {
    const sbmOptions = {
        id: "tx_fn_FileDown",
        method: "post",
        action: "/common/fileupload.do",
        ref: "dma_FileDownReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/valueup/resoroom.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnDetail_ajaxsubmit
 * @description fn Detail ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnDetail_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnDetail_ajaxsubmit",
        method: "post",
        action: "/valueup/resoroom.do",
        ref: "dma_fnDetailAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name keyEvent
 * @description key Event 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.keyEvent = async function (e) {
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) === 13 || (typeof e !== 'undefined' && e === 13)) {
        if ($c.util.getKeyCode(event) === 13) {
            await scwin.fnSearch();
        }
    }
};

/**
 * @method
 * @name fnSearchInit
 * @description fn Search Init 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchInit = async function () {
    $c.util.getComponent("dma_FileDownReq").set("pageIndex", "1");
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnAllSearch
 * @description fn All Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnAllSearch = async function () {
    $c.util.getComponent('ipt_title').setValue("");
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    scwin.closeDetail();
    if ($(document).find("select[id=ipt_currentPageSize]").val() != null) {
        $c.util.getComponent("dma_FileDownReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    }
    $c.util.getComponent("dma_FileDownReq").set("method", "valueupResoroomSub");
    $c.util.getComponent("dma_FileDownReq").set("forward", "valueupResoroom_sub");
    await scwin.tx_fnSearch_ajaxsubmit();
};

/**
 * @method
 * @name fnDetail
 * @description fn Detail 처리
 * @param {*} val val
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDetail = async function (val) {
    $(document).find('div[id=detail]').css("display", "block");
    $c.util.getComponent("dma_FileDownReq").set("method", "valueupResoroomSubDetail");
    $c.util.getComponent("dma_FileDownReq").set("forward", "valueupResoroom_detail");
    $c.util.getComponent("dma_FileDownReq").set("contnId", val);
    await scwin.tx_fnDetail_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchCallBack1
 * @description fn Search Call Back1 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack1 = function (data) {
    (($c.util.getComponent('contents')) && ($c.util.getComponent('contents')).removeAll ? ($c.util.getComponent('contents')).removeAll() : (($c.util.getComponent('contents')) && ($c.util.getComponent('contents')).setValue ? ($c.util.getComponent('contents')).setValue('') : void 0)).append(data);
    $("tr:odd").addClass("active");
};

/**
 * @method
 * @name fnSearchCallBack2
 * @description fn Search Call Back2 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack2 = function (data) {
    (($c.util.getComponent('detail')) && ($c.util.getComponent('detail')).removeAll ? ($c.util.getComponent('detail')).removeAll() : (($c.util.getComponent('detail')) && ($c.util.getComponent('detail')).setValue ? ($c.util.getComponent('detail')).setValue('') : void 0)).append(data);
};

/**
 * @method
 * @name fnSearch1
 * @description fn Search1 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch1 = async function () {
    $c.util.getComponent("dma_FileDownReq").set("pageIndex", "1");
    $c.util.getComponent("dma_FileDownReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    await scwin.fnSearch();
};

/**
 * @method
 * @name fileDown
 * @description file Down 처리
 * @param {String} ipt_resoroomId ipt_resoroomId
 * @param {*} ipt_attachSeq ipt_attachSeq
 * @param {String} ipt_attachFileNm ipt_attachFileNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileDown = async function (ipt_resoroomId, ipt_attachSeq, ipt_attachFileNm) {
    $c.util.getComponent("dma_FileDownReq").set("method", "searchNoticeFile");
    $c.util.getComponent("dma_FileDownReq").set("resoroomId", ipt_resoroomId);
    $c.util.getComponent("dma_FileDownReq").set("attachSeq", ipt_attachSeq);
    $c.util.getComponent("dma_FileDownReq").set("attachFileNm", ipt_attachFileNm);
    await scwin.tx_fn_FileDown();
};

/**
 * @method
 * @name closeDetail
 * @description close Detail 처리
 * @returns {void}
 * @hidden N
 */
scwin.closeDetail = function () {
    (($c.util.getComponent('detail')) && ($c.util.getComponent('detail')).removeAll ? ($c.util.getComponent('detail')).removeAll() : (($c.util.getComponent('detail')) && ($c.util.getComponent('detail')).setValue ? ($c.util.getComponent('detail')).setValue('') : void 0));
    $(document).find('div[id=detail]').css("display", "none");
};
